<?php
// HOTELINX.ID — single-file landing page
// Configure this address and ensure PHP mail() is enabled on your hosting.
$recipient = 'sales@hotelinx.com';
$sent = false;
$error = '';

if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['contact_submit'])) {
    // Honeypot anti-spam field
    if (!empty($_POST['website'])) {
        $sent = true;
    } else {
        $name = trim(filter_input(INPUT_POST, 'name', FILTER_UNSAFE_RAW) ?? '');
        $email = trim(filter_input(INPUT_POST, 'email', FILTER_UNSAFE_RAW) ?? '');
        $company = trim(filter_input(INPUT_POST, 'company', FILTER_UNSAFE_RAW) ?? '');
        $subject = trim(filter_input(INPUT_POST, 'subject', FILTER_UNSAFE_RAW) ?? 'Website enquiry');
        $message = trim(filter_input(INPUT_POST, 'message', FILTER_UNSAFE_RAW) ?? '');

        if ($name === '' || !filter_var($email, FILTER_VALIDATE_EMAIL) || $message === '') {
            $error = 'Please complete your name, a valid email address, and message.';
        } else {
            $safeSubject = preg_replace('/[\r\n]+/', ' ', $subject);
            $mailSubject = 'Hotelinx.id Enquiry — ' . $safeSubject;
            $body = "New enquiry from Hotelinx.id\n\n"
                  . "Name: {$name}\nEmail: {$email}\nCompany: {$company}\n"
                  . "Subject: {$safeSubject}\n\nMessage:\n{$message}\n";
            $headers = "From: Hotelinx Website <no-reply@" . ($_SERVER['HTTP_HOST'] ?? 'hotelinx.id') . ">\r\n"
                     . "Reply-To: {$email}\r\n"
                     . "Content-Type: text/plain; charset=UTF-8\r\n";
            if (mail($recipient, $mailSubject, $body, $headers)) {
                $sent = true;
            } else {
                $error = 'Your message could not be sent right now. Please email sales@hotelinx.com directly.';
            }
        }
    }
}
